#!/usr/bin/env bash
# Revert only edits generated by prepare_device.sh before an intentional repo sync.
set -eo pipefail

SRC_ROOT="$(cd "${1:?Usage: restore_before_sync.sh /path/to/android-source}" && pwd)"
DEVICE_DIR="$SRC_ROOT/device/oplus/zephyr"

if [[ -d "$DEVICE_DIR/.git" || -f "$DEVICE_DIR/.git" ]]; then
  git -C "$DEVICE_DIR" checkout -- AndroidProducts.mk vendorsetup.sh
fi
rm -f "$DEVICE_DIR/custom_zephyr.mk"

# Undo only our marked Android 17 libmnl edit before refreshing upstream sources.
LIBMNL_BP="$SRC_ROOT/external/libmnl/Android.bp"
if [[ -f "$LIBMNL_BP" ]] && grep -q 'PIXEL_OS_ZEPHYR_ANDROID17_LIBMNL_PARTITION_FIX' "$LIBMNL_BP"; then
  python3 - "$LIBMNL_BP" <<'PY'
from pathlib import Path
import re
import sys

path = Path(sys.argv[1])
text = path.read_text(encoding="utf-8")
pattern = re.compile(
    r'(?m)^(?P<indent>[ \t]*)// PIXEL_OS_ZEPHYR_ANDROID17_LIBMNL_PARTITION_FIX:.*\n'
    r'(?P=indent)// vendor_available: true,\n'
)
updated, count = pattern.subn(lambda m: f'{m.group("indent")}vendor_available: true,\n', text, count=1)
if count != 1:
    raise SystemExit(f"Found the libmnl fix marker but could not restore its original property in {path}")
path.write_text(updated, encoding="utf-8")
print("Restored external/libmnl/Android.bp before source refresh.")
PY
fi

# Restore vendor Android.bp files changed to remove duplicate Bluetooth HIDL prebuilts.
VENDOR_DIR="$SRC_ROOT/vendor/oplus/zephyr"
if [[ -d "$VENDOR_DIR" ]] && git -C "$VENDOR_DIR" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  while IFS= read -r -d '' bp; do
    if grep -q 'PIXEL_OS_ZEPHYR_ANDROID17_BT_HIDL_PREBUILT_FIX' "$bp"; then
      rel_path="$(python3 -c 'import os,sys; print(os.path.relpath(sys.argv[1], sys.argv[2]))' "$bp" "$VENDOR_DIR")"
      if git -C "$VENDOR_DIR" ls-files --error-unmatch "$rel_path" >/dev/null 2>&1; then
        git -C "$VENDOR_DIR" checkout -- "$rel_path"
        echo "Restored $rel_path before source refresh."
      else
        echo "ERROR: marked vendor Android.bp is not tracked by its Repo project: $rel_path" >&2
        exit 1
      fi
    fi
  done < <(find "$VENDOR_DIR" -type f -name Android.bp -print0)
fi

echo "Restored generated device-tree edits before source refresh."
